mapper.select:
SELECT bbd.org_id AS orgId, bbd.executor_id AS dentistId, bbd.item_type AS itemType, bbd.item_id AS itemId, SUM(IFNULL(bbps.free_amount, 0)) AS freePaymentWorkload, SUM(IFNULL(bbps.received_amount, 0)) AS receivedWorkload FROM base_bill_detail bbd LEFT JOIN base_bill_pay_share bbps ON bbps.bill_detail_id=bbd.bill_detail_id INNER JOIN base_bill_pay bbp ON bbp.bill_pay_id=bbps.bill_pay_id
bbps.inservice = true AND DATE_FORMAT(bbp.payee_date, '%Y%m%d') = #{payDate} AND bbd.org_id = #{orgId} AND bbd.executor_id = #{executorId} AND bbd.item_type = #{itemType} AND bbd.item_id = #{itemId}
GROUP BY bbd.org_id, bbd.executor_id, bbps.item_type, bbps.item_id
